// createSignerSubjects returns the factory of the subjects of CreateSigner
// that calls newSubject with the handle of each check.
func createSignerSubjects[T blob.CreateSigner](
	newSubject func(h *CreateSignerHandle) T,
) func(h *CreateSignerHandle) blob.CreateSigner {
	return func(h *CreateSignerHandle) blob.CreateSigner { return newSubject(h) }
}

// createSignerSignCreateCalls generates the calls of
// CreateSigner.SignCreate with the inputs that each case draws.
var createSignerSignCreateCalls = prop.Composite(func(c *prop.Case) func(context.Context, blob.CreateSigner) error {
	key := c.Draw(prop.Of[string](), "key")
	contentType := c.Draw(prop.Of[string](), "content-type")
	size := c.Draw(prop.Of[int64](), "size")
	expiry := c.Draw(prop.Of[time.Time](), "expiry")
	return func(ctx context.Context, subject blob.CreateSigner) error {
		_, err := subject.SignCreate(ctx, key, contentType, size, expiry)
		return err
	}
})

// createSignerOverEmbedded is blob.CreateSigner under the name of the
// field that createSignerOver embeds.
type createSignerOverEmbedded = blob.CreateSigner

// createSignerOver is a subject of CreateSigner whose callables call spend
// and return their zero results. The planted defect of a ceiling passes a
// spend that exceeds the ceiling.
type createSignerOver struct {
	createSignerOverEmbedded
	spend func()
}

// SignCreate calls spend and returns its zero results.
func (o createSignerOver) SignCreate(
	context.Context,
	string,
	string,
	int64,
	time.Time,
) (r0 blob.SignedRequest, r1 error) {
	o.spend()
	return r0, r1
}

// newCreateSignerOver returns the planted defect of a ceiling of
// CreateSigner, whose callables call spend.
func newCreateSignerOver(_ *CreateSignerHandle, spend func()) blob.CreateSigner {
	return createSignerOver{spend: spend}
}

// createSignerSignCreatePanicsDefect is the planted defect of a
// CreateSigner whose SignCreate panics.
type createSignerSignCreatePanicsDefect struct {
	createSignerOverEmbedded
}

// SignCreate is the override of the planted defect.
func (*createSignerSignCreatePanicsDefect) SignCreate(
	p0 context.Context,
	p1, p2 string,
	p3 int64,
	p4 time.Time,
) (r0 blob.SignedRequest, r1 error) {
	panic("the planted defect of a CreateSigner whose SignCreate panics")
}

// createSignerSignCreatePanics returns the planted defect of a
// CreateSigner whose SignCreate panics over a fresh subject.
func createSignerSignCreatePanics(h *CreateSignerHandle) blob.CreateSigner {
	return &createSignerSignCreatePanicsDefect{createSignerOverEmbedded: h.Fresh()}
}

// createSignerSignCreateIgnoresCancelDefect is the planted defect of a
// CreateSigner whose SignCreate ignores the context.
type createSignerSignCreateIgnoresCancelDefect struct {
	createSignerOverEmbedded
}

// SignCreate is the override of the planted defect.
func (d *createSignerSignCreateIgnoresCancelDefect) SignCreate(
	p0 context.Context,
	p1, p2 string,
	p3 int64,
	p4 time.Time,
) (r0 blob.SignedRequest, r1 error) {
	if p0.Err() != nil {
		return r0, r1
	}
	return d.createSignerOverEmbedded.SignCreate(p0, p1, p2, p3, p4)
}

// createSignerSignCreateIgnoresCancel returns the planted defect of a
// CreateSigner whose SignCreate ignores the context over a fresh subject.
func createSignerSignCreateIgnoresCancel(h *CreateSignerHandle) blob.CreateSigner {
	return &createSignerSignCreateIgnoresCancelDefect{createSignerOverEmbedded: h.Fresh()}
}

